#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EngineConfig { pub model_path: String, pub whisper_model_path: Option<String>, pub style: String, pub llama_server_path: Option<String>, pub whisper_path: Option<String>, #[serde(default)] pub server_args: Vec<String> }
impl Default for EngineConfig { fn default() -> Self { Self { model_path: String::new(), whisper_model_path: None, style: "chat".into(), llama_server_path: None, whisper_path: None, server_args: vec!["--ctx-size".into(), "24576".into(), "--parallel".into(), "1".into(), "--no-mmap".into()] } } }

fn now_stamp() -> String { format!("{} Meeting", Local::now().format("%Y-%m-%d %H%M")) }
pub(crate) fn documents_root() -> PathBuf { std::env::var_os("USERPROFILE").map(PathBuf::from).or_else(|| std::env::var_os("HOME").map(PathBuf::from)).unwrap_or_else(|| PathBuf::from(".")) .join("Documents").join(APP_FOLDER) }
pub(crate) fn support_root() -> PathBuf { std::env::var_os("APPDATA").map(PathBuf::from).or_else(|| std::env::var_os("HOME").map(|p| PathBuf::from(p).join(".config"))).unwrap_or_else(|| PathBuf::from(".")) .join(APP_FOLDER) }
fn unix_now() -> String { Utc::now().to_rfc3339() }

fn metadata(folder: &Path) -> serde_json::Value { fs::read_to_string(folder.join("meta.json")).ok().and_then(|x| serde_json::from_str(&x).ok()).unwrap_or(serde_json::json!({})) }
pub fn include_in_brain(folder: &Path) -> bool { metadata(folder).get("includeInBrain").and_then(|x| x.as_bool()).unwrap_or(true) }
fn set_include(folder: &Path, value: bool) -> Result<(), String> { let mut object = metadata(folder); let map = object.as_object_mut().ok_or("Meeting metadata is invalid.")?; map.insert("includeInBrain".into(), serde_json::Value::Bool(value)); fs::write(folder.join("meta.json"), serde_json::to_vec_pretty(&object).map_err(|e| e.to_string())?).map_err(|e| e.to_string()) }

fn load_meeting(folder: &Path) -> Option<Meeting> { let notes = fs::read_to_string(folder.join("notes.md")).unwrap_or_default(); let transcript = fs::read_to_string(folder.join("transcript.md")).unwrap_or_default(); if notes.is_empty() && transcript.is_empty() { return None; } let name = folder.file_name()?.to_string_lossy().to_string(); let title = notes.lines().next().unwrap_or(&name).trim_start_matches("# ").to_string(); let meta = metadata(folder); let started = meta.get("started").and_then(|v| v.as_str()).unwrap_or("").to_string(); Some(Meeting { id: folder.to_string_lossy().to_string(), folder: folder.to_string_lossy().to_string(), title, date: name.get(..10).unwrap_or("").to_string(), started, notes, transcript, include_in_brain: include_in_brain(folder) }) }
pub(crate) fn list_saved_meetings() -> Vec<Meeting> { let mut meetings = fs::read_dir(documents_root()).ok().into_iter().flatten().filter_map(|e| e.ok()).filter_map(|e| load_meeting(&e.path())).collect::<Vec<_>>(); meetings.sort_by(|a,b| b.folder.cmp(&a.folder)); meetings }

#[tauri::command] fn list_meetings() -> Vec<Meeting> { list_saved_meetings() }
#[tauri::command] fn get_meeting(id: String) -> Result<Meeting, String> { load_meeting(Path::new(&id)).ok_or_else(|| "Meeting not found".into()) }
#[tauri::command] fn meeting_delete_confirmation() -> &'static str { DELETE_CONFIRMATION }
#[tauri::command] fn set_include_in_brain(folder: String, included: bool, state: tauri::State<'_, AppState>) -> Result<(), String> { set_include(Path::new(&folder), included)?; if !included { BrainStore::open_default()?.remove_meeting_data(&folder)?; } else { let _ = state; } Ok(()) }
#[tauri::command] fn delete_meeting(folder: String, state: tauri::State<'_, AppState>) -> Result<(), String> { if state.recording.lock().map_err(|_| "Recorder lock failed")?.as_ref().map(|r| r.folder.to_string_lossy() == folder).unwrap_or(false) { return Err("This meeting is still being recorded.".into()); } BrainStore::open_default()?.remove_meeting_data(&folder)?; trash::delete(&folder).map_err(|e| e.to_string()) }

// ----- The exact small-talk boundary from Chat.swift -----
pub fn needs_records(question: &str) -> bool { let normalized = question.to_lowercase().replace("'s", " is").replace("'re", " are").replace("'m", " am"); let words: Vec<_> = normalized.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()).collect(); if words.is_empty() { return false; } let small: HashSet<&str> = ["a","about","afternoon","all","am","an","and","are","assistant","bye","can","do","doing","evening","fine","for","going","good","great","hello","help","helpful","hey","hi","how","i","inferoid","is","it","me","morning","much","my","name","nice","night","ok","okay","please","so","tell","thank","thanks","that","the","there","to","today","up","very","well","what","who","yo","you","your","yourself"].into_iter().collect(); !words.iter().all(|word| small.contains(word)) }

pub fn terms(text: &str) -> Vec<String> { const STOP: &[&str] = &["the","a","an","and","or","of","to","in","on","for","is","was","are","were","what","who","when","where","why","how","did","do","does","we","i","you","it","that","this","with","at","by","be","about","from","our","my","me","them","they","any","all","which","there","have","has","had"]; text.to_lowercase().split(|c: char| !c.is_alphanumeric()).filter(|x| x.len()>1 && !STOP.contains(x)).map(ToOwned::to_owned).collect() }
pub fn bm25_search(query: &str, meetings: &[Meeting], limit: usize) -> Vec<(String, f64)> { let meetings: Vec<_> = meetings.iter().filter(|m| m.include_in_brain).collect(); let q: HashSet<_> = terms(query).into_iter().collect(); if q.is_empty() { return vec![]; } let docs: Vec<HashMap<String, usize>> = meetings.iter().map(|m| { let mut tf=HashMap::new(); for t in terms(&m.notes) { *tf.entry(t).or_insert(0)+=2; } for t in terms(&m.transcript) { *tf.entry(t).or_insert(0)+=1; } tf }).collect(); let lengths: Vec<f64> = docs.iter().map(|d| d.values().sum::<usize>() as f64).collect(); let avg=(lengths.iter().sum::<f64>()/lengths.len().max(1) as f64).max(1.0); let n=docs.len() as f64; let mut out=Vec::new(); for (i,doc) in docs.iter().enumerate() { let mut score=0.0; for term in &q { if let Some(&f)=doc.get(term) { let df=docs.iter().filter(|d| d.contains_key(term)).count() as f64; let idf=(1.0+(n-df+0.5)/(df+0.5)).ln(); let ff=f as f64; score += idf*ff*2.2/(ff+1.2*(0.25+0.75*lengths[i]/avg)); } } if score>0.0 { out.push((meetings[i].id.clone(),score)); } } out.sort_by(|a,b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal)); out.truncate(limit); out }

pub fn inkling_render(system: &str, turns: &[ChatTurn]) -> String { let mut out=format!("<|message_system|><|content_text|>{}<|end_message|><|message_system|><|content_text|>Thinking effort level: 0<|end_message|>", clean(system)); for t in turns { let role=if t.role=="assistant" {"message_model"} else {"message_user"}; out.push_str(&format!("<|{}|><|content_text|>{}<|end_message|>",role,clean(&t.text))); if t.role=="assistant" { out.push_str("<|content_model_end_sampling|>"); } } out.push_str("<|message_model|><|content_text|>"); out }
pub fn inkling_prefix(system: &str, turns: &[ChatTurn], partial: &str) -> String { let mut out=inkling_render(system,turns); let suffix="<|message_model|><|content_text|>"; out.truncate(out.len()-suffix.len()); out.push_str(&format!("<|message_user|><|content_text|>{}",clean(partial))); out }
fn clean(value: &str) -> String { value.replace("<|", "< |") }
#[derive(Debug, Clone, PartialEq)] pub struct ChatTurn { pub role: String, pub text: String }

// ----- llama.cpp supervision and exact model protocol -----
pub struct EngineSupervisor { child: Option<Child>, pub port: Option<u16>, pub style: String, pub log: Arc<Mutex<Vec<String>>> }
impl EngineSupervisor { pub fn new() -> Self { Self { child: None, port: None, style: "chat".into(), log: Arc::new(Mutex::new(Vec::new())) } } pub fn free_port() -> Result<u16,String> { let listener=TcpListener::bind("127.0.0.1:0").map_err(|e|e.to_string())?; listener.local_addr().map(|a|a.port()).map_err(|e|e.to_string()) } pub fn stop(&mut self) { if let Some(mut child)=self.child.take() { let _=child.kill(); let _=child.wait(); } self.port=None; } pub fn start(&mut self, config: EngineConfig) -> Result<u16,String> { self.stop(); stop_stale_servers(); if config.model_path.is_empty() { return Err("Choose a model path in the engine config first.".into()); } let port=Self::free_port()?; let binary=config.llama_server_path.unwrap_or_else(|| if cfg!(windows) { "llama-server.exe".into() } else { "llama-server".into() }); let mut cmd=Command::new(binary); cmd.arg("--model").arg(&config.model_path).arg("--port").arg(port.to_string()); cmd.args(&config.server_args).stdout(Stdio::null()).stderr(Stdio::piped()); let mut child=cmd.spawn().map_err(|e|format!("Could not start llama-server: {e}"))?; if let Some(stderr)=child.stderr.take() { let log=Arc::clone(&self.log); thread::spawn(move || { let mut reader=std::io::BufReader::new(stderr); let mut line=String::new(); loop { line.clear(); if reader.read_line(&mut line).unwrap_or(0)==0 { break; } if let Ok(mut l)=log.lock() { let trimmed=line.trim().to_string(); if trimmed.to_lowercase().contains("out of memory") || trimmed.to_lowercase().contains("failed to allocate") { l.push("Not enough memory; close other apps and try again.".into()); } l.push(trimmed); } } }); } self.style=config.style; self.child=Some(child); self.port=Some(port); Ok(port) } }
fn stop_stale_servers() { if cfg!(windows) { let _=Command::new("taskkill").args(["/IM","llama-server.exe","/F"]).output(); } else { let _=Command::new("pkill").args(["-f","llama-server"]).output(); } }
fn health_check(port: u16) -> bool { let Ok(mut stream)=TcpStream::connect_timeout(&std::net::SocketAddr::from(([127,0,0,1],port)),Duration::from_secs(2)) else {return false}; let _=stream.write_all(b"GET /health HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n"); let mut buf=[0;256]; let n=stream.read(&mut buf).unwrap_or(0); String::from_utf8_lossy(&buf[..n]).contains("200") }
/// Starts llama-server from engine.json if it is not running yet, then waits (up to 3 minutes) for the model to load.
pub(crate) fn ensure_engine(engine:&Mutex<EngineSupervisor>)->Result<(),String>{ let port={ let mut e=engine.lock().map_err(|_|"Engine lock failed".to_string())?; if let Some(p)=e.port { if health_check(p) { return Ok(()); } } let config=load_engine_config(); if config.model_path.is_empty() { return Err("No model is set up yet. Add model_path to engine.json in the Inferoid Notes settings folder.".into()); } e.start(config)? }; for _ in 0..360 { if health_check(port) { return Ok(()); } thread::sleep(Duration::from_millis(500)); } Err("The model is still loading. Try again in a moment.".into()) }
#[tauri::command] fn start_engine(config: EngineConfig, state: tauri::State<'_, AppState>) -> Result<u16,String> { state.engine.lock().map_err(|_|"Engine lock failed".to_string())?.start(config) }
#[tauri::command] fn stop_engine(state: tauri::State<'_, AppState>) { if let Ok(mut e)=state.engine.lock() { e.stop(); } }
#[tauri::command] fn engine_status(state: tauri::State<'_, AppState>) -> serde_json::Value { let e=state.engine.lock().unwrap(); serde_json::json!({"port":e.port,"healthy":e.port.map(health_check).unwrap_or(false),"log":e.log.lock().map(|l|l.clone()).unwrap_or_default()}) }

// ----- Portable Brain SQLite schema -----
pub struct BrainStore { path: PathBuf }
impl BrainStore { pub fn open_default() -> Result<Self,String> { let path=support_root().join("brain.sqlite"); fs::create_dir_all(path.parent().unwrap()).map_err(|e|e.to_string())?; let store=Self{path}; store.init()?; Ok(store) } fn conn(&self)->Result<Connection,String>{Connection::open(&self.path).map_err(|e|e.to_string())} fn init(&self)->Result<(),String>{ let c=self.conn()?; c.execute_batch("PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS episodes(id TEXT PRIMARY KEY, meeting_folder TEXT NOT NULL UNIQUE, started_at TEXT NOT NULL, processed_at TEXT, model TEXT); CREATE TABLE IF NOT EXISTS entities(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, name TEXT NOT NULL, world TEXT NOT NULL DEFAULT 'unknown', summary TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, forgotten INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS aliases(entity_id INTEGER NOT NULL REFERENCES entities(id), alias_norm TEXT NOT NULL, alias_display TEXT NOT NULL, source TEXT NOT NULL, PRIMARY KEY(entity_id,alias_norm)); CREATE TABLE IF NOT EXISTS facts(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, subject_id INTEGER REFERENCES entities(id), predicate TEXT NOT NULL, object_id INTEGER REFERENCES entities(id), value TEXT NOT NULL DEFAULT '', owner_id INTEGER REFERENCES entities(id), counterparty_id INTEGER REFERENCES entities(id), due TEXT, done INTEGER NOT NULL DEFAULT 0, valid_from TEXT NOT NULL, invalidated_at TEXT, superseded_by INTEGER REFERENCES facts(id), status TEXT NOT NULL DEFAULT 'verified', confidence REAL NOT NULL DEFAULT 0.0, episode_id TEXT NOT NULL REFERENCES episodes(id), line_start INTEGER NOT NULL DEFAULT 0, line_end INTEGER NOT NULL DEFAULT 0, quote TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, embedding BLOB); CREATE TABLE IF NOT EXISTS corrections(id INTEGER PRIMARY KEY AUTOINCREMENT,fact_id INTEGER NOT NULL REFERENCES facts(id),action TEXT NOT NULL,old_json TEXT NOT NULL,new_json TEXT NOT NULL,created_at TEXT NOT NULL); CREATE VIRTUAL TABLE IF NOT EXISTS facts_fts USING fts5(value, quote, content='facts', content_rowid='id'); CREATE VIRTUAL TABLE IF NOT EXISTS entities_fts USING fts5(name, summary, content='entities', content_rowid='id'); CREATE TRIGGER IF NOT EXISTS facts_ai AFTER INSERT ON facts BEGIN INSERT INTO facts_fts(rowid,value,quote) VALUES(new.id,new.value,new.quote); END; CREATE TRIGGER IF NOT EXISTS facts_ad AFTER DELETE ON facts BEGIN INSERT INTO facts_fts(facts_fts,rowid,value,quote) VALUES('delete',old.id,old.value,old.quote); END; CREATE TRIGGER IF NOT EXISTS facts_au AFTER UPDATE OF value,quote ON facts BEGIN INSERT INTO facts_fts(facts_fts,rowid,value,quote) VALUES('delete',old.id,old.value,old.quote); INSERT INTO facts_fts(rowid,value,quote) VALUES(new.id,new.value,new.quote); END; CREATE TRIGGER IF NOT EXISTS entities_ai AFTER INSERT ON entities BEGIN INSERT INTO entities_fts(rowid,name,summary) VALUES(new.id,new.name,new.summary); END; CREATE TRIGGER IF NOT EXISTS entities_ad AFTER DELETE ON entities BEGIN INSERT INTO entities_fts(entities_fts,rowid,name,summary) VALUES('delete',old.id,old.name,old.summary); END; CREATE TRIGGER IF NOT EXISTS entities_au AFTER UPDATE OF name,summary ON entities BEGIN INSERT INTO entities_fts(entities_fts,rowid,name,summary) VALUES('delete',old.id,old.name,old.summary); INSERT INTO entities_fts(rowid,name,summary) VALUES(new.id,new.name,new.summary); END; PRAGMA user_version=2;").map_err(|e|e.to_string()) }
 pub fn remove_meeting_data(&self, folder: &str)->Result<(),String>{let mut c=self.conn()?; let tx=c.transaction().map_err(|e|e.to_string())?; let ids:Vec<String>={let mut st=tx.prepare("SELECT id FROM episodes WHERE meeting_folder=?").map_err(|e|e.to_string())?; let rows:Vec<String>=st.query_map([folder],|r|r.get(0)).map_err(|e|e.to_string())?.filter_map(Result::ok).collect(); rows}; for id in &ids {tx.execute("UPDATE facts SET superseded_by=NULL,invalidated_at=NULL WHERE superseded_by IN (SELECT id FROM facts WHERE episode_id=?1)",[id]).map_err(|e|e.to_string())?; tx.execute("DELETE FROM corrections WHERE fact_id IN (SELECT id FROM facts WHERE episode_id=?1)",[id]).map_err(|e|e.to_string())?; tx.execute("DELETE FROM facts WHERE episode_id=?1",[id]).map_err(|e|e.to_string())?; tx.execute("DELETE FROM episodes WHERE id=?1",[id]).map_err(|e|e.to_string())?;} tx.commit().map_err(|e|e.to_string()) }
 pub fn add_person(&self,name:&str,world:&str,summary:&str,email:&str)->Result<(),String>{let c=self.conn()?; let now=unix_now(); c.execute("INSERT INTO entities(kind,name,world,summary,created_at,updated_at) VALUES('person',?,?,?,?,?)",params![name,parse_world(world),summary,&now,&now]).map_err(|e|e.to_string())?; let id=c.last_insert_rowid(); c.execute("INSERT OR IGNORE INTO aliases(entity_id,alias_norm,alias_display,source) VALUES(?,?,?,'manual')",params![id,name.to_lowercase(),name]).map_err(|e|e.to_string())?; if !email.is_empty(){c.execute("INSERT OR IGNORE INTO aliases(entity_id,alias_norm,alias_display,source) VALUES(?,?,?,'manual')",params![id,email.to_lowercase(),email]).map_err(|e|e.to_string())?;} Ok(()) }
 pub fn orbit(&self)->Result<Vec<OrbitPerson>,String>{let c=self.conn()?; let mut st=c.prepare("SELECT id,name,world,summary FROM entities WHERE kind='person' AND forgotten=0 ORDER BY updated_at DESC").map_err(|e|e.to_string())?; let rows=st.query_map([],|r|Ok(OrbitPerson{id:r.get(0)?,name:r.get(1)?,world:parse_world(&r.get::<_,String>(2)?),summary:r.get(3)?,meeting_count:0,last_met:None})).map_err(|e|e.to_string())?; Ok(rows.filter_map(Result::ok).collect())}
}
#[derive(Debug, Clone, Serialize)] pub struct OrbitPerson { pub id:i64, pub name:String, pub world:String, pub summary:String, #[serde(rename="meetingCount")] pub meeting_count:i64, #[serde(rename="lastMet",skip_serializing_if="Option::is_none")] pub last_met:Option<String> }
fn parse_world(raw:&str)->String{match raw.trim().to_lowercase().as_str(){"friend"|"family"|"other"=>raw.trim().to_lowercase(),"business"|"client"|"opposing"|"court"|"team"=>"business".into(),"personal"=>"friend".into(),_=>"unknown".into()}}
#[tauri::command] fn orbit()->Result<Vec<OrbitPerson>,String>{BrainStore::open_default()?.orbit()}
#[tauri::command] fn add_person(name:String,world:String,summary:String,email:String)->Result<(),String>{BrainStore::open_default()?.add_person(&name,&world,&summary,&email)}

// ----- Windows recording boundary -----
pub trait AudioRecorder: Send { fn start(&mut self, folder:&Path)->Result<(),String>; fn stop(&mut self)->Result<(),String>; }
pub struct MacRecorder;
impl AudioRecorder for MacRecorder { fn start(&mut self,_:&Path)->Result<(),String>{Err("macOS recording is not implemented in Inferoid Desktop v1; Windows WASAPI is the first target.".into())} fn stop(&mut self)->Result<(),String>{Ok(())} }
#[cfg(windows)] mod windows_audio {
    use super::*;
    use cpal::traits::{DeviceTrait, HostTrait, StreamTrait};
    use std::fs::File;
    use std::io::BufWriter;
    use std::sync::Arc;
    // cpal streams are not Send on WASAPI, so they live on their own thread until stop() signals it.
    pub struct WindowsWasapiRecorder { stop_tx: Option<std::sync::mpsc::Sender<()>>, thread: Option<thread::JoinHandle<()>>, writers: Option<Arc<Mutex<AudioWriters>>> }
    struct AudioWriters { me:hound::WavWriter<BufWriter<File>>, them:hound::WavWriter<BufWriter<File>>, mixed:hound::WavWriter<BufWriter<File>> }
    fn writers(folder:&Path)->Result<AudioWriters,String>{let spec=hound::WavSpec{channels:1,sample_rate:16_000,bits_per_sample:16,sample_format:hound::SampleFormat::Int};Ok(AudioWriters{me:hound::WavWriter::create(folder.join("audio-me.wav"),spec).map_err(|e|e.to_string())?,them:hound::WavWriter::create(folder.join("audio-them.wav"),spec).map_err(|e|e.to_string())?,mixed:hound::WavWriter::create(folder.join("audio.wav"),spec).map_err(|e|e.to_string())?})}
    trait AudioValue { fn as_f32(self)->f32; }
    impl AudioValue for f32 { fn as_f32(self)->f32{self} }
    impl AudioValue for i16 { fn as_f32(self)->f32{self as f32/32768.0} }
    impl AudioValue for u16 { fn as_f32(self)->f32{self as f32/32768.0-1.0} }
    fn push<T: Copy + AudioValue>(data:&[T], channels:usize, source_rate:u32, target:&mut hound::WavWriter<BufWriter<File>>, mixed:&mut hound::WavWriter<BufWriter<File>>){let stride=(source_rate as f32/16_000.0).max(1.0);let mut position=0.0;while (position as usize)*channels<data.len(){let index=position as usize*channels;let value=data[index].as_f32().clamp(-1.0,1.0);let pcm=(value*32767.0) as i16;let _=target.write_sample(pcm);let _=mixed.write_sample(pcm);position+=stride;}}
    fn build<T: Copy + Send + 'static + AudioValue + cpal::SizedSample>(device:cpal::Device, config:cpal::StreamConfig, writers:Arc<Mutex<AudioWriters>>, me:bool)->Result<cpal::Stream,String>{let channels=config.channels as usize;let rate=config.sample_rate.0;let error=move |e|eprintln!("Inferoid audio stream: {e}");let stream=device.build_input_stream(&config,move |data:&[T],_|{if let Ok(mut guard)=writers.lock(){let w=&mut *guard;if me{push(data,channels,rate,&mut w.me,&mut w.mixed)}else{push(data,channels,rate,&mut w.them,&mut w.mixed)} }},error,None).map_err(|e|e.to_string())?;stream.play().map_err(|e|e.to_string())?;Ok(stream)}
    impl WindowsWasapiRecorder { pub fn new()->Self{Self{stop_tx:None,thread:None,writers:None}} }
    impl AudioRecorder for WindowsWasapiRecorder {
        fn start(&mut self,folder:&Path)->Result<(),String>{
            let writers=Arc::new(Mutex::new(writers(folder)?));
            self.writers=Some(Arc::clone(&writers));
            let (stop_tx,stop_rx)=std::sync::mpsc::channel::<()>();
            let (ready_tx,ready_rx)=std::sync::mpsc::channel::<Result<(),String>>();
            let handle=thread::spawn(move || {
                let open=|| -> Result<Vec<cpal::Stream>,String> {
                    let host=cpal::host_from_id(cpal::HostId::Wasapi).map_err(|e|e.to_string())?;
                    let mic=host.default_input_device().ok_or("No WASAPI microphone was found")?;
                    let output=host.default_output_device().ok_or("No WASAPI output device was found for loopback")?;
                    let mic_config=mic.default_input_config().map_err(|e|e.to_string())?;
                    let out_config=output.default_input_config().map_err(|e|format!("WASAPI loopback is unavailable for the default output device: {e}"))?;
                    let mic_stream=match mic_config.sample_format(){cpal::SampleFormat::F32=>build::<f32>(mic,mic_config.into(),Arc::clone(&writers),true)?,cpal::SampleFormat::I16=>build::<i16>(mic,mic_config.into(),Arc::clone(&writers),true)?,cpal::SampleFormat::U16=>build::<u16>(mic,mic_config.into(),Arc::clone(&writers),true)?,_=>return Err("Unsupported microphone sample format".into())};
                    let out_stream=match out_config.sample_format(){cpal::SampleFormat::F32=>build::<f32>(output,out_config.into(),Arc::clone(&writers),false)?,cpal::SampleFormat::I16=>build::<i16>(output,out_config.into(),Arc::clone(&writers),false)?,cpal::SampleFormat::U16=>build::<u16>(output,out_config.into(),Arc::clone(&writers),false)?,_=>return Err("Unsupported WASAPI loopback sample format".into())};
                    Ok(vec![mic_stream,out_stream])
                };
                match open() {
                    Ok(streams)=>{ let _=ready_tx.send(Ok(())); let _=stop_rx.recv(); drop(streams); }
                    Err(e)=>{ let _=ready_tx.send(Err(e)); }
                }
            });
            match ready_rx.recv() {
                Ok(Ok(()))=>{ self.stop_tx=Some(stop_tx); self.thread=Some(handle); Ok(()) }
                Ok(Err(e))=>{ let _=handle.join(); self.writers=None; Err(e) }
                Err(_)=>{ self.writers=None; Err("The audio thread stopped unexpectedly".into()) }
            }
        }
        fn stop(&mut self)->Result<(),String>{
            if let Some(tx)=self.stop_tx.take(){ let _=tx.send(()); }
            if let Some(handle)=self.thread.take(){ let _=handle.join(); }
            if let Some(writers)=self.writers.take(){
                // The streams (and their clones of the writers) are gone, so this is the last reference.
                let w=Arc::try_unwrap(writers).map_err(|_|"Audio is still being written".to_string())?.into_inner().map_err(|_|"Audio writer lock failed".to_string())?;
                w.me.finalize().map_err(|e|e.to_string())?; w.them.finalize().map_err(|e|e.to_string())?; w.mixed.finalize().map_err(|e|e.to_string())?;
            }
            Ok(())
        }
    }
}
#[cfg(windows)] use windows_audio::WindowsWasapiRecorder;
pub struct RecordingSession { pub folder:PathBuf, recorder:Box<dyn AudioRecorder> }
#[tauri::command] fn start_recording(state:tauri::State<'_,AppState>)->Result<String,String>{let folder=documents_root().join(now_stamp()); fs::create_dir_all(&folder).map_err(|e|e.to_string())?; let mut recorder:Box<dyn AudioRecorder>=Box::new(MacRecorder); #[cfg(windows)] { recorder=Box::new(WindowsWasapiRecorder::new()); } recorder.start(&folder)?; let session=RecordingSession{folder:folder.clone(),recorder}; *state.recording.lock().map_err(|_|"Recorder lock failed")?=Some(session); Ok(folder.to_string_lossy().into())}
